import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.HashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;

public class ECommerceDemo {

    public static class Product {
        final String id;
        final String name;
        final long priceCents;
        final double rating;
        int stockQuantity;

        public Product(String id, String name, long priceCents, double rating, int stock) {
            this.id = id;
            this.name = name;
            this.priceCents = priceCents;
            this.rating = rating;
            this.stockQuantity = stock;
        }

        @Override
        public String toString() {
            return name + " ($" + (priceCents / 100.0) + ", ★" + rating + ")";
        }
    }

    public static class Store {
        final Map<String, Product> inventory = new HashMap<>();
        final Map<String, Integer> cart = new HashMap<>();
        final LinkedHashSet<Product> browsingHistory = new LinkedHashSet<>();

        public void addProduct(Product p) {
            inventory.put(p.id, p);
        }

        public void recordView(Product p) {
            browsingHistory.remove(p);
            browsingHistory.add(p);
        }

        public void addToCart(String productId, int quantity) {
            Product p = inventory.get(productId);
            if (p == null) throw new IllegalArgumentException("Product not found");
            if (quantity <= 0) throw new IllegalArgumentException("Quantity must be positive");

            int currentInCart = cart.getOrDefault(productId, 0);
            if (currentInCart + quantity > p.stockQuantity) {
                throw new IllegalStateException("Insufficient stock for " + p.name);
            }
            cart.merge(productId, quantity, Integer::sum);
            System.out.println("[CART] Added " + quantity + "x " + p.name);
        }

        public List<Product> getCatalogSortedByRatingThenPrice() {
            List<Product> list = new ArrayList<>(inventory.values());
            Comparator<Product> comp = Comparator
                .comparingDouble((Product p) -> p.rating).reversed()
                .thenComparingLong(p -> p.priceCents);
            Collections.sort(list, comp);
            return list;
        }

        public long checkout() {
            if (cart.isEmpty()) throw new IllegalStateException("Cart is empty");
            long totalCents = 0;

            // Deduct stock
            for (Map.Entry<String, Integer> entry : cart.entrySet()) {
                Product p = inventory.get(entry.getKey());
                int qty = entry.getValue();
                p.stockQuantity -= qty;
                totalCents += (p.priceCents * qty);
            }
            cart.clear();
            return totalCents;
        }
    }

    public static void main(String[] args) {
        Store store = new Store();
        Product p1 = new Product("P1", "Headphones", 19999, 4.8, 10);
        Product p2 = new Product("P2", "Keyboard", 8999, 4.8, 20);
        Product p3 = new Product("P3", "Monitor", 49999, 4.5, 5);

        store.addProduct(p1);
        store.addProduct(p2);
        store.addProduct(p3);

        System.out.println("Catalog sorted: " + store.getCatalogSortedByRatingThenPrice());

        store.recordView(p1);
        store.recordView(p3);
        store.recordView(p1); // Re-view p1
        System.out.println("Browsing history: " + store.browsingHistory);

        store.addToCart("P1", 2);
        store.addToCart("P1", 1); // Merge -> 3
        store.addToCart("P2", 1);

        long totalCents = store.checkout();
        System.out.println("Checkout complete! Total: $" + (totalCents / 100.0));
        System.out.println("Remaining P1 stock: " + p1.stockQuantity);
    }
}
