import java.util.Map;

public class SubtotalCalculator {
    public static long calculateSubtotal(Map<String, Integer> cart, Map<String, Long> priceMap) {
        if (cart == null || priceMap == null) return 0L;
        long total = 0;
        for (Map.Entry<String, Integer> entry : cart.entrySet()) {
            Long price = priceMap.get(entry.getKey());
            if (price != null && entry.getValue() != null) {
                total += price * entry.getValue();
            }
        }
        return total;
    }
}

