import java.util.Map;

public class AtomicInventoryDeductor {
    public static boolean tryDeductInventory(Map<String, Integer> stock, Map<String, Integer> cart) {
        if (stock == null || cart == null) return false;
        // Step 1: Validation phase
        for (Map.Entry<String, Integer> entry : cart.entrySet()) {
            int available = stock.getOrDefault(entry.getKey(), 0);
            if (available < entry.getValue()) {
                return false; // Insufficient stock, abort without mutation
            }
        }
        // Step 2: Mutation phase
        for (Map.Entry<String, Integer> entry : cart.entrySet()) {
            stock.put(entry.getKey(), stock.get(entry.getKey()) - entry.getValue());
        }
        return true;
    }
}
